def bfs_path(src,dst):
    prev={src:None}; q=deque([src])
    while q:
        r,c=q.popleft()
        if (r,c)==dst:
            path=[]; cur=dst
            while cur: path.append(cur); cur=prev[cur]
            return path[::-1]
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(r+dr,c+dc)
            if 0<=n[0]<H and 0<=n[1]<W and inp[n[0]][n[1]]!=2 and n not in prev:
                prev[n]= (r,c); q.append(n)
    return None
